<template><section class="item-editor metric-editor"><header><h4>{{ title }} *</h4><button type="button" @click="$emit('add')"><Plus :size="15" />추가</button></header><article v-for="(item,index) in items" :key="index"><template v-if="type==='comparison'"><div class="metric-fields"><input v-model="item.metric_name" placeholder="지표명" /><input v-model="item.before_value" placeholder="Before" /><input v-model="item.after_value" placeholder="After" /><input v-model="item.improvement_rate" placeholder="개선율" /></div></template><template v-else><div class="metric-fields kpi"><input v-model="item.metric_name" placeholder="성능 지표명" /><input v-model="item.value" placeholder="측정값" /></div><textarea v-model="item.description" rows="2" placeholder="측정 기준과 결과를 설명하세요."></textarea></template><button type="button" :disabled="items.length===1" @click="$emit('remove',index)"><X :size="15" /></button></article></section></template>
<script setup>import{Plus,X}from"lucide-vue-next";defineProps({title:String,items:Array,type:String});defineEmits(["add","remove"]);</script>
